import csv
import json


def answer() -> int:
    qualifying_children = {
        ("Liwia", "Maligłówka"),
        ("Alan", "Wocial"),
    }

    total = 0
    with open("/app/dataset/people_accounts.csv", newline="", encoding="utf-8") as f:
        for person in csv.DictReader(f):
            if (person["first_name"], person["last_name"]) in qualifying_children:
                total += int(person["account_balance"])
    return total


if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
